export const message=(error:unknown)=>error instanceof Error?error.message:String(error);
function MarkdownContent({value}:{value:string}) {return <TaskMarkdown source={value}/>;}
function snapshotMarkdown(taskId:string,instruction:TaskInstruction,markdown=instruction.snapshot.descriptionMd) {return instruction.snapshot.attachments.reduce((value,file)=>{const url=`/api/task-mode/tasks/${taskId}/instructions/${instruction.id}/attachments/${file.id}`;return (file.previewUrl?value.replaceAll(file.previewUrl,url):value).replaceAll(file.url,url);},markdown);}
export function ModeStatus({status}:{status:string}) {const color=({not_started:"todo",in_progress:"running",recovering:"recovering",pending_manual_acceptance:"acceptance",awaiting_authorization:"confirmation",pending_auto_acceptance:"running",done:"done",blocked:"blocked",paused:"paused"} as Record<string,string>)[status]??"todo";return <span className="tp-status" data-status={color} title={STATUS_DESCRIPTIONS[status]}><span className="tp-dot"/>{STATUS_NAMES[status]??status}</span>;}
export function TaskHeartbeat({state}:{state:TaskModeState}) {
  const [clock,setClock]=useState(Date.now());
  useEffect(()=>{const timer=setInterval(()=>setClock(Date.now()),5000);return()=>clearInterval(timer);},[]);
  const active=["planning","working","reviewing"].includes(state.phase),heartbeat=state.heartbeat;
  const outputReadFailure=state.runs.find(run=>run.id===state.activeRunId)?.jobs.some(isTaskOutputFailure);
  const blockedResult=state.phase==="blocked"?state.runs.find(run=>run.id===state.activeRunId)?.result:undefined;
  const stale=active&&heartbeat?.status==="healthy"&&heartbeat.checkedAt&&clock-Date.parse(heartbeat.checkedAt)>15000;
  const mode=stale?"recovering":heartbeat?.status??"idle";
  const label=active&&!heartbeat?"心跳尚未启用 · 请重启 Apron"
    :active&&heartbeat?.status==="idle"&&!heartbeat.checkedAt?"等待首次心跳"
    :mode==="recovering"?(heartbeat?.message?.includes("读取")?heartbeat.message:heartbeat?.status==="recovering"?`正在自动恢复 · 第 ${heartbeat.recoveryAttempts} 次尝试`:"心跳超时 · 正在检查连接")
    :mode==="needs_attention"?(outputReadFailure?"汇报读取失败 · 原始结果已保留":heartbeat?.recoveryAttempts?"自动恢复失败 · 需要处理":"任务处理失败 · 需要处理")
    :state.phase==="awaiting_authorization"?"待确认 · 等待批准授权":active?"任务心跳正常":state.phase==="paused"?"任务已暂停":state.phase==="blocked"?"本轮未完成 · 执行已暂停":state.phase==="completed"||state.phase==="needs_confirmation"?"本轮执行已结束":"等待任务开始";
  return <div className={`tm-task-heartbeat state-${mode}`} role="status"><HeartPulse/><strong>{label}</strong>{heartbeat?.checkedAt&&<span>上次确认 {new Date(heartbeat.checkedAt).toLocaleTimeString()}</span>}{heartbeat?.lastEventAt&&<span>最近 Codex 活动 {new Date(heartbeat.lastEventAt).toLocaleTimeString()}</span>}{mode==="recovering"&&heartbeat?.nextRetryAt&&<span>下次检查 {new Date(heartbeat.nextRetryAt).toLocaleTimeString()}</span>}{mode==="needs_attention"&&heartbeat?.message&&<span className="tm-heartbeat-error">{heartbeat.message}</span>}{blockedResult&&<span className="tm-heartbeat-blocker">暂停原因：{blockedResult.risks[0]||blockedResult.summary}</span>}</div>;
}
