      pending.current=restored.map(({id,file,url})=>({id,file,url}));
      const content=restored.reduce((value,item)=>value.replaceAll(item.oldUrl,item.url),fields.descriptionMd);
      const recovered:StoredTaskDraft={...latest.current,...(draft?{project:draft.project,repository:draft.repository,priority:draft.priority,tags:draft.tags??[],executionMode:draft.executionMode??settings.executionMode??"collaborative"}:{}),title:fields.title,description:content,acceptance:fields.acceptanceCriteriaMd,taskId:task?.id??draft?.taskId,files:restored.map(item=>({id:item.id,name:item.file.name,mimeType:item.file.type,url:item.url,file:item.file}))};
      publishRequestId.current=draft?.publishRequestId??publishRequestId.current;recovered.publishRequestId=publishRequestId.current;latest.current=recovered;markdownRef.current=content;
