  if(!draftReady)return <ModeDialog title={task?"编辑任务":"新建任务"} onClose={()=>void closeForm()} closeOnBackdrop={false} closeOnEscape={false}><p className="tp-small tp-muted" role="status">正在读取未提交的草稿…</p></ModeDialog>;
