    record=await taskApi.update(record.id,{title:saving.title.trim(),descriptionMd:md,acceptanceCriteriaMd:saving.acceptance,repositoryPath:saving.repository,project:saving.project,priority:saving.priority,tags:saving.tags??[],revision:record.revision});setCurrent(record);latest.current.taskId=record.id;
