export function SettingsPanel({settings,taskId,onSaved}:{settings:TaskModeSettings;taskId?:string;onSaved:()=>void}) {
  const [value,setValue]=useState(()=>({...DEFAULT_TASK_MODE_SETTINGS,...settings})),[models,setModels]=useState<TaskConversationModel[]>([]),[error,setError]=useState(""),[modelError,setModelError]=useState(""),[busy,setBusy]=useState(false),[saved,setSaved]=useState(false),[fullAccess,setFullAccess]=useState(false);
  useEffect(()=>{let active=true;void taskModeApi.models().then(result=>{if(active)setModels(result.models);}).catch(error=>{if(active)setModelError(message(error));});return()=>{active=false;};},[]);
  const field=<K extends keyof TaskModeSettings>(key:K,next:TaskModeSettings[K])=>{setValue(old=>key==="authorizationType"?applyTaskAuthorization({...old,permissionPreset:old.authorizationType==="full_authorization"?"workspace_write":old.permissionPreset,[key]:next}):({...old,[key]:next}));setSaved(false);};
  async function save(){setBusy(true);setError("");try{await taskModeApi.saveSettings(value,taskId,fullAccess);setSaved(true);onSaved();}catch(error){setError(message(error));}finally{setBusy(false);}}
  return <section className="tp-settings"><h1>{taskId?"当前任务设置":"代理设置"}</h1><p className="tp-page-sub">{taskId?"新的配置用于下一轮执行，当前运行使用其发送时的设置。":"新任务使用这些默认设置。已有任务可以单独调整。"}</p><div className="tp-setting-group"><h3>模型</h3><datalist id="tm-models">{models.map(model=><option key={model.id} value={model.id}>{model.displayName}</option>)}</datalist><div className="tp-setting-grid"><label className="tm-field">任务代理<input className="tp-input" list="tm-models" value={value.agentModel} onChange={event=>field("agentModel",event.target.value)}/></label><label className="tm-field" hidden={value.executionMode==="quick"}>Worker 模型<input className="tp-input" list="tm-models" value={value.workerModel} onChange={event=>field("workerModel",event.target.value)}/></label></div>{modelError&&<p className="tp-small tm-error">无法读取可用模型：{modelError}</p>}<label className="tm-field" style={{marginTop:15}}>推理强度<select className="tp-select" value={value.effort} onChange={event=>field("effort",event.target.value as TaskModeSettings["effort"])}>{["low","medium","high","xhigh"].map(effort=><option key={effort}>{effort}</option>)}</select></label></div><div className="tp-setting-group"><h3>执行模式</h3><label className="tm-field">执行模式<select className="tp-select" value={value.executionMode??"collaborative"} onChange={event=>field("executionMode",event.target.value as TaskModeSettings["executionMode"])}><option value="collaborative">协作模式</option><option value="quick">快速模式 · 消息代理直接执行</option></select></label>{value.executionMode==="quick"?<p className="tp-small tp-muted">消息代理直接修改代码、验证并汇报，不分配 Worker。</p>:<><h3>Worker 协作方式</h3><div className="tp-policy-grid">{Object.entries(POLICY_NAMES).map(([key,label])=><button key={key} className="tp-policy" aria-pressed={value.workerPolicy===key} onClick={()=>field("workerPolicy",key as TaskModeSettings["workerPolicy"])}><strong>{label}</strong><small>{key==="single"?"一个 Worker 串行执行":key==="parallel"?"优先拆分独立的工作":"代理判断是否需要并行"}</small></button>)}</div><label className="tm-field" style={{marginTop:15}}>最多同时执行的 Worker<select className="tp-select" disabled={value.workerPolicy==="single"} value={value.maxWorkers} onChange={event=>field("maxWorkers",Number(event.target.value))}>{[1,2,3,4,6,8].map(n=><option key={n}>{n}</option>)}</select></label></>}</div><div className="tp-setting-group"><h3>执行审批</h3><label className="tm-field">授权类型<select className="tp-select" aria-label="授权类型" value={value.authorizationType??""} onChange={event=>field("authorizationType",(event.target.value||undefined) as TaskAuthorizationType|undefined)}><option value="">沿用现有审批策略</option><option value="pending_approval">待批准</option><option value="full_authorization">完全授权</option></select></label><p className="tp-small tp-muted">完全授权在任务目标内持续执行，包含修改、验证及任务已要求的发布；待批准会展示具体授权请求。</p>{value.authorizationType!=="full_authorization"&&<label className="tm-field">审批策略<select className="tp-select" aria-label="审批策略" disabled={Boolean(value.authorizationType)} value={value.approvalsReviewer} onChange={event=>field("approvalsReviewer",event.target.value as TaskModeSettings["approvalsReviewer"])}><option value="auto_review">Codex 代我审批（默认）</option><option value="user">由我手动审批</option></select></label>}<p className="tp-small tp-muted" style={{marginTop:8}}>根据授权类型执行：待批准时展示请求；完全授权时在任务目标内直接执行。缺失信息仍会明确提示。保存后用于下一轮执行，当前轮次保持发送时的审批策略。完全授权会直接执行已授权的任务动作。</p></div><div className="tp-setting-grid"><label className="tm-field">{value.executionMode==="quick"?"消息代理权限":"Worker 权限"}<select className="tp-select" disabled={value.authorizationType==="full_authorization"} value={value.permissionPreset} onChange={event=>field("permissionPreset",event.target.value as TaskModeSettings["permissionPreset"])}><option value="read_only">只读</option><option value="workspace_write">允许修改项目目录</option><option value="full_access">完全访问</option></select></label><label className="tm-field">结果验收<select className="tp-select" disabled={value.authorizationType==="full_authorization"} value={value.reviewPolicy} onChange={event=>field("reviewPolicy",event.target.value as TaskModeSettings["reviewPolicy"])}><option value="artifacts">有审查附件时人工验收</option><option value="always">每轮都需要人工验收</option><option value="agent">{value.authorizationType==="full_authorization"?"自动完成，不等待人工确认":"代理决定是否需要确认"}</option></select></label></div>{value.permissionPreset==="full_access"&&value.authorizationType!=="full_authorization"&&<label className="tm-check"><input type="checkbox" checked={fullAccess} onChange={event=>setFullAccess(event.target.checked)}/>确认允许执行者访问项目目录以外的文件并执行命令。</label>}<div className="tp-setting-group"><label className="tm-field">代理系统提示词<textarea className="tp-textarea" value={value.executionMode==="quick"&&value.agentPrompt===DEFAULT_TASK_MODE_SETTINGS.agentPrompt?QUICK_TASK_MODE_AGENT_PROMPT:value.agentPrompt} onChange={event=>field("agentPrompt",event.target.value)}/></label><label className="tm-field" hidden={value.executionMode==="quick"} style={{marginTop:15}}>Worker 系统提示词<textarea className="tp-textarea" value={value.workerPrompt} onChange={event=>field("workerPrompt",event.target.value)}/></label></div>{error&&<p className="tm-error" role="alert">{error}</p>}<div className="tp-row tp-between"><span className="tp-small tp-muted" role="status">{saved?"设置已保存到服务器":""}</span><button className="tp-button tp-primary" disabled={busy||value.permissionPreset==="full_access"&&value.authorizationType!=="full_authorization"&&!fullAccess} onClick={()=>void save()}><Save/>保存设置</button></div></section>;
}

export function TaskAttachmentManager({task,onChanged,onReference}:{task:TaskItem;onChanged:()=>Promise<void>;onReference:(file:TaskAttachment)=>void}) {
  const [removing,setRemoving]=useState<TaskAttachment|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState("");
  async function remove(){if(!removing)return;setBusy(true);setError("");let deleted=false;try{await taskApi.deleteAttachment(task.id,removing.id);deleted=true;setRemoving(null);setNotice("附件已删除，已发送的需求快照保留。");await onChanged();}catch(error){setError(deleted?`附件已删除，但列表刷新失败，请刷新页面：${message(error)}`:message(error));}finally{setBusy(false);}}
  return <section className="tp-attachment-manager" aria-label="任务附件管理"><h3>任务附件管理</h3><p className="tp-small tp-muted">用户输入附件随指示保存；AI 反馈材料仅在明确引用时加入需求快照。</p>{(["input","feedback"] as const).map(source=>{const files=task.attachments.filter(file=>(file.source??"input")===source);return <div key={source}><h4>{source==="input"?"用户输入附件":"AI 反馈材料"} · {files.length}</h4><div className="tm-managed-attachments">{files.map(file=><div className="tm-managed-attachment" key={file.id}><a className="tp-attachment" href={file.previewUrl??file.url} target="_blank" rel="noreferrer">{file.mimeType.startsWith("image/")?<img className="tp-file-thumb" src={file.url} alt=""/>:<Paperclip/>}{file.name}</a><button className="tp-button tp-small" disabled={busy} aria-label={`引用附件 ${file.name}`} onClick={()=>onReference(file)}>引用到指示</button><button className="tp-button tp-small tm-delete-button" disabled={busy} aria-label={`删除附件 ${file.name}`} onClick={()=>{setError("");setRemoving(file);}}><Trash2/>删除</button></div>)}</div>{files.length===0&&<p className="tp-small tp-muted">暂无{source==="input"?"输入附件":"反馈材料"}</p>}</div>;})}{notice&&<p role="status">{notice}</p>}{error&&!removing&&<p className="tm-error" role="alert">{error}</p>}{removing&&<ModeDialog title="删除附件" onClose={()=>{if(!busy)setRemoving(null);}}><p>删除“{removing.name}”？已发送指示的原文与附件快照会保留。</p>{error&&<p className="tm-error" role="alert">{error}</p>}<div className="tp-row"><button className="tp-button" disabled={busy} onClick={()=>setRemoving(null)}>取消</button><button className="tp-button tm-delete-button" disabled={busy} onClick={()=>void remove()}>确认删除附件</button></div></ModeDialog>}</section>;
}

interface WorkspaceProps { detail:TaskModeDetail; tasks:TaskItem[]; documents:TaskModeDocument[]; layout:"board"|"desk"|"document"; conversationRequest?:number; onBack:()=>void; onEdit:()=>void; onSettings:()=>void; refresh:()=>Promise<void>; onNotice:(text:string)=>void; resize?:ReactNode; onTaskLifecycle:(task:TaskItem,action:"archive"|"restore"|"delete")=>void }
export function TaskWorkspace({detail,tasks,documents,layout,conversationRequest=0,onBack,onEdit,onSettings,refresh,onNotice,resize,onTaskLifecycle}:WorkspaceProps) {
  const {task,state}=detail;const [authorizationType,setAuthorizationType]=useState<TaskAuthorizationType|undefined>(state.settings.authorizationType);const [text,setText]=useState(""),[timing,setTiming]=useState<"now"|"after">("now"),[busy,setBusy]=useState(false),[error,setError]=useState(""),[tab,setTab]=useState<"work"|"activity"|"conversation">("work");const composer=useRef<HTMLDivElement>(null);const [files,setFiles]=useState<TaskAttachment[]>([]);const requestId=useRef(createClientId());const [snapshot,setSnapshot]=useState<TaskInstruction|null>(null);
  const [instructionView,setInstructionView]=useState<"active"|"archived">("active"),[deleteInstruction,setDeleteInstruction]=useState<TaskInstruction|null>(null);
  const currentInstructions=state.instructions.filter(entry=>!entry.deletedAt&&!entry.archivedAt);
  const archivedInstructions=state.instructions.filter(entry=>!entry.deletedAt&&entry.archivedAt);
  const visibleInstructions=state.instructions.map((instruction,index)=>({instruction,index})).filter(({instruction})=>!instruction.deletedAt&&(instructionView==="archived"?Boolean(instruction.archivedAt):!instruction.archivedAt));
  const latestVisibleId=visibleInstructions.at(-1)?.instruction.id;
  const latestReply=[...state.instructions].reverse().find(entry=>entry.agentReply&&!entry.deletedAt&&!entry.archivedAt);
  const currentTaskUpdate=latestAcceptedTaskUpdate(state)||latestReply?.agentReply;
  async function manageInstruction(entry:TaskInstruction,action:"archive"|"restore"|"delete"){
    setBusy(true);setError("");try{await taskModeApi.instructionAction(task.id,entry.id,action);if(action==="delete")setDeleteInstruction(null);await refresh();onNotice(action==="archive"?"需求已归档，可在归档需求中恢复。":action==="restore"?"需求已恢复。":"需求已从列表删除，已发送的执行记录保留。");}catch(error){setError(message(error));}finally{setBusy(false);}
  }
  const [stepOverrides,setStepOverrides]=useState<Record<string,boolean>>(()=>readStepOverrides(task.id));
  useEffect(()=>{try{window.localStorage.setItem(stepExpansionKey(task.id),JSON.stringify(stepOverrides));}catch{/* Keep manual choices in memory when browser storage is unavailable. */}},[task.id,stepOverrides]);
  const expandedStep=(stepId:string,latest:boolean)=>stepOverrides[stepId]??latest;
  const toggleStep=(stepId:string,latest:boolean)=>setStepOverrides(previous=>({...previous,[stepId]:!(previous[stepId]??latest)}));
  const jumpWorkspace=(edge:"top"|"bottom")=>{
    const scroller=document.scrollingElement??document.documentElement;
    window.scrollTo({top:edge==="top"?0:scroller.scrollHeight,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth"});
  };
  useEffect(()=>{if(conversationRequest)setTab("conversation");},[conversationRequest]);
  const status=detail.approvals.length?"awaiting_authorization":visibleStatus(task,{phase:state.phase,instructionCount:state.instructions.filter(entry=>!entry.deletedAt).length,heartbeat:state.heartbeat});
  const outputReadFailure=state.runs.find(run=>run.id===state.activeRunId)?.jobs.some(isTaskOutputFailure);
  const currentResult=state.runs.find(run=>run.id===state.activeRunId)?.result;
  const needsGuidance=Boolean(currentResult&&!hasTaskActionGuidance(currentResult));
  const focusComposer=()=>{setTab("work");setTimeout(()=>{composer.current?.scrollIntoView({behavior:"smooth",block:"center"});composer.current?.querySelector<HTMLElement>('[contenteditable="true"]')?.focus();},0);};
  async function submit(initial=false){const content=initial?"按照任务描述和验收标准开始执行。":text;if(!content.trim()){setError("请填写下一步指示");return;}setBusy(true);setError("");try{await taskModeApi.submit(task.id,{clientMessageId:requestId.current,text:content,timing,authorizationType,attachmentIds:[...new Set([...files.map(file=>file.id),...task.attachments.filter(file=>content.includes(file.url)||(file.previewUrl&&content.includes(file.previewUrl))).map(file=>file.id)])],...referencesFromMarkdown(task.descriptionMd+"\n"+content,task.id)});requestId.current=createClientId();setText("");setFiles([]);await refresh();onNotice("指示已保存，等待代理接收。");}catch(error){setError(message(error));}finally{setBusy(false);}}
  async function action(action:"pause"|"resume"|"retry"|"approve"|"approve_authorization"|"reread_output"|"clarify_report",runId?:string){setBusy(true);setError("");try{await taskModeApi.action(task.id,action,runId,action==="approve_authorization"?{approvalTokens:detail.approvals.map(item=>item.token),authorizationRevision:state.revision}:undefined);await refresh();}catch(error){setError(message(error));}finally{setBusy(false);}}
  const header=<div className="tp-detail-heading"><div className="tp-row"><ModeStatus status={status}/><span className="tp-mono tp-muted">{task.key}</span></div><div className="tp-detail-title"><h1>{task.title}</h1><div className="tp-task-actions">{!task.archived&&(detail.approvals.length>0||state.phase==="awaiting_authorization")&&<button className="tp-button tp-primary" disabled={busy} onClick={()=>void action("approve_authorization")}><Check/>批准授权</button>}<button className="tp-button" onClick={onEdit}><FileText/>编辑需求</button><button className="tp-button" onClick={()=>setTab("conversation")}><MessageSquare/>Codex 对话</button>{task.archived?null:!state.instructions.some(entry=>!entry.deletedAt)?<button className="tp-button tp-primary" disabled={busy} onClick={()=>void submit(true)}><Play/>开始执行</button>:<button className="tp-button" onClick={focusComposer}><Plus/>添加下一步指示</button>}{!task.archived&&["planning","working","reviewing"].includes(state.phase)&&<button className="tp-button" disabled={busy} onClick={()=>void action("pause")}><Pause/>暂停</button>}{!task.archived&&["paused","blocked"].includes(state.phase)&&<button className="tp-button" disabled={busy} onClick={()=>void action(state.phase==="paused"?"resume":outputReadFailure?"reread_output":needsGuidance?"clarify_report":"retry")}><Play/>{state.phase==="paused"?"恢复执行":outputReadFailure?"重新读取汇报":needsGuidance?"补齐行动说明":"继续执行剩余工作"}</button>}<button className="tp-button" onClick={()=>onTaskLifecycle(task,task.archived?"restore":"archive")}>{task.archived?<ArchiveRestore/>:<Archive/>}{task.archived?"恢复任务":"归档任务"}</button><button className="tp-button tm-delete-button" onClick={()=>onTaskLifecycle(task,"delete")}><Trash2/>删除任务</button></div></div><div className="tp-context-strip"><span><Folder/>{task.repositoryPath||"尚未设置项目工作目录"}</span><span>{task.project||"未分配项目"}</span><button className="tp-button tp-ghost" onClick={onSettings}><Settings2/>执行设置</button></div><TaskTagControl task={task} refresh={refresh} onNotice={onNotice}/>{currentTaskUpdate&&<section className="tm-agent-update" aria-label="当前任务进展"><h3><Bot/>当前任务进展</h3><MarkdownContent value={currentTaskUpdate}/></section>}{task.archived&&<div className="tp-alert">此任务已归档，执行已停止。恢复任务后可手动继续执行。</div>}<TaskHeartbeat state={state}/><TaskUsagePanel usage={detail.usage}/><TaskStatusGuide state={state} latestReport={task.latestReport} approvalCount={detail.approvals.length}/></div>;
  const original=<><section className="tp-original"><div className="tp-section-caption"><span><FileText/>原始需求</span><span className="tp-small tp-muted">版本 {task.revision}</span></div><div className="tp-rich"><MarkdownContent value={task.descriptionMd}/></div>{task.acceptanceCriteriaMd&&<div className="tp-acceptance"><h3>验收标准</h3><MarkdownContent value={task.acceptanceCriteriaMd}/></div>}</section><TaskAttachmentManager task={task} onChanged={async()=>{const current=await taskApi.get(task.id);setFiles(previous=>previous.filter(file=>current.attachments.some(item=>item.id===file.id)));await refresh();}} onReference={file=>{setFiles(previous=>previous.some(item=>item.id===file.id)?previous:[...previous,file]);setText(previous=>`${previous}\n[${file.name}](${file.url})`);requestId.current=createClientId();focusComposer();}}/></>;
  const compose=<section className="tp-compose" ref={composer}><div className="tp-row tp-between"><h3>添加下一步指示</h3><span className="tp-small tp-muted">保留在当前任务的记录中</span></div><label className="tm-field">授权类型<select className="tp-select" aria-label="发送指示授权类型" value={authorizationType??""} disabled={busy} onChange={event=>setAuthorizationType((event.target.value||undefined) as TaskAuthorizationType|undefined)}><option value="">沿用任务设置</option><option value="pending_approval">待批准</option><option value="full_authorization">完全授权</option></select><span className="tp-small tp-muted">当前轮次保持发送时的授权。变更授权的追加指示将在下一轮执行。</span></label><RichTaskEditor label="下一步指示" value={text} onChange={value=>{if(!busy)requestId.current=createClientId();setText(value);}} upload={async selected=>{const uploaded=await taskModeApi.upload(task.id,selected);setFiles(old=>[...old,...uploaded.attachments]);return uploaded.attachments;}} tasks={tasks.filter(item=>item.id!==task.id)} documents={documents} disabled={busy}/><div className="tp-compose-foot"><select className="tp-inline-select" aria-label="追加指示执行时机" value={timing} onChange={event=>setTiming(event.target.value as typeof timing)}><option value="now">立即补充给代理</option><option value="after">当前轮次完成后执行</option></select><button className="tp-button tp-primary" disabled={busy||!text.trim()} onClick={()=>void submit()}>{busy?<Loader2/>:<ArrowUp/>}发送给代理</button></div>{files.length>0&&<div className="tp-small tp-muted">已附加 {files.length} 个文件</div>}</section>;
  const activeRun=state.runs.find(run=>run.id===state.activeRunId);const shownSettings=activeRun?.settings??state.settings;const quick=shownSettings.executionMode==="quick";const agent=<aside className="tp-agent-panel"><section><div className="tp-agent-title"><span className="tp-avatar">A</span><div><h3>{quick?"消息代理 · 直接执行":"任务代理"}</h3><div className="tp-small tp-muted">{shownSettings.agentModel}</div></div></div><p className="tp-small tp-muted">{state.phase==="working"&&quick?"直接修改、验证与汇报":({idle:"等待开始执行",planning:"理解需求与拆分任务",working:"持续跟进 Worker",reviewing:"检查结果与验证证据",paused:"已暂停",awaiting_authorization:"等待授权批准",blocked:"执行遇到阻塞",needs_confirmation:"等待人工验收",completed:"本轮已完成，可继续追加"})[state.phase]}</p></section>{quick?<section><div className="tp-side-label">直接执行</div>{activeRun?.jobs.filter(job=>job.role==="execute").map(job=><details key={job.id}><summary>{job.name} · {jobStatus(job)}</summary>{job.error&&<p className="tm-error">{job.error}</p>}</details>)}<p className="tp-small tp-muted">全程不分配 Worker</p></section>:<section><div className="tp-side-label">WORKERS</div>{activeRun?.jobs.filter(job=>job.role==="worker").map(job=><details className="tp-worker" key={job.id}><summary>{job.name} · {jobStatus(job)}</summary><p className="tp-small">{job.objective}</p><p className="tp-small tp-muted">{job.ownedPaths.join(", ")}</p>{job.error&&<p className="tm-error">{job.error}</p>}</details>)??<p className="tp-small tp-muted">尚未分配</p>}</section>}<section><div className="tp-side-label">执行方式</div><div>{quick?"快速模式 · 消息代理直接执行":POLICY_NAMES[shownSettings.workerPolicy]}</div>{!quick&&<p className="tp-small tp-muted">最多 {shownSettings.workerPolicy==="single"?1:shownSettings.maxWorkers} 个 Worker</p>}</section><button className="tp-button" onClick={onSettings}><Settings2/>执行设置</button></aside>;
  const approvals=detail.approvals.map(approval=><section className="tp-alert" key={approval.token}><strong>待确认 · 授权请求</strong><pre>{approval.command?.display||approval.fileChange?.paths.join("\n")||"未提供受影响文件，无法判断修改范围。请拒绝并让 Codex 重新说明。"}</pre><p>{approval.command?.reason||approval.fileChange?.reason}</p><div className="tp-row"><button className="tp-button" disabled={busy||(approval.kind==="file_change"&&!approval.fileChange?.paths.length)} onClick={()=>void resolve(approval.token,approval.threadId,"accept")}>允许本次</button><button className="tp-button" disabled={busy} onClick={()=>void resolve(approval.token,approval.threadId,"decline")}>拒绝</button></div></section>);
  const authorizationDetails=(detail.approvals.length>0||state.phase==="awaiting_authorization")?<section className="tp-authorization-details" aria-label="具体需要授权的内容"><h3>具体需要授权的内容</h3>{detail.approvals.length?approvals:null}{state.phase==="awaiting_authorization"&&<><p>{currentResult?.stopReason}</p>{currentResult?.humanActions?.map((item,index)=><div className="tp-alert" key={index}><strong>{item.action}</strong><p>{item.reason}</p><p>批准后：{item.unblocks}</p></div>)}</>}</section>:null;
  async function resolve(token:string,threadId:string,decision:"accept"|"decline"){setBusy(true);try{await taskConversationApi.resolveApproval(task.id,threadId,token,decision);await refresh();}catch(error){setError(message(error));}finally{setBusy(false);}}
  const timeline=<div className="tp-timeline"><div className="tm-instruction-views" role="group" aria-label="需求记录范围"><button className="tp-filter" aria-pressed={instructionView==="active"} onClick={()=>setInstructionView("active")}>当前需求 {currentInstructions.length}</button><button className="tp-filter" aria-pressed={instructionView==="archived"} onClick={()=>setInstructionView("archived")}><Archive/>归档需求 {archivedInstructions.length}</button></div>{visibleInstructions.map(({instruction,index})=><section className={`tp-step ${instruction.id===latestVisibleId?"tp-latest":""}`} key={instruction.id} data-instruction-id={instruction.id}><span className="tp-step-index">{String(index+1).padStart(2,"0")}</span><div className="tp-step-head"><button type="button" className="tm-step-toggle" aria-expanded={expandedStep(instruction.id,instruction.id===latestVisibleId)} aria-controls={`tm-step-body-${instruction.id}`} onClick={()=>toggleStep(instruction.id,instruction.id===latestVisibleId)}><ChevronRight/><span className="tm-step-name">{index?"追加指示":"首次执行"}</span><time className="tp-small tp-muted" dateTime={instruction.createdAt}>{new Date(instruction.createdAt).toLocaleString()}</time><span className="tm-step-toggle-label">{expandedStep(instruction.id,instruction.id===latestVisibleId)?"收起":"展开"}</span></button><div className="tm-step-actions"><button className="tp-button tp-ghost tp-small" disabled={busy} aria-label={`${instruction.archivedAt?"恢复":"归档"}第 ${index+1} 条需求`} onClick={()=>void manageInstruction(instruction,instruction.archivedAt?"restore":"archive")}>{instruction.archivedAt?<ArchiveRestore/>:<Archive/>}{instruction.archivedAt?"恢复":"归档"}</button><button className="tp-button tp-ghost tp-small tm-delete-button" disabled={busy} aria-label={`删除第 ${index+1} 条需求`} onClick={()=>setDeleteInstruction(instruction)}><Trash2/>删除</button></div></div>{!expandedStep(instruction.id,instruction.id===latestVisibleId)&&<p className="tm-step-preview" title={instruction.text}>{instruction.text.replace(/\s+/g," ").slice(0,120)}</p>}{expandedStep(instruction.id,instruction.id===latestVisibleId)&&<div id={`tm-step-body-${instruction.id}`} className="tm-step-body"><div className="tp-instruction"><MarkdownContent value={snapshotMarkdown(task.id,instruction,instruction.text)}/></div>{instruction.agentReply&&<details className="tm-agent-reply-record"><summary>查看代理对这条消息的答复</summary><MarkdownContent value={instruction.agentReply}/></details>}{instruction.replyOnly?<p className="tp-small tp-muted">进度答复已保存，原任务按既定目标继续执行。</p>:<div className="tp-delivery"><span className="tp-delivered">✓ 已保存</span><span>→</span><span className={instruction.agentReceivedAt?"tp-delivered":""}>{instruction.agentReceivedAt?"✓ ":""}代理已接收</span>{(state.runs.find(run=>run.id===instruction.runId)?.settings.executionMode??state.settings.executionMode)!=="quick"&&<><span>→</span><span className={instruction.workerReceivedAt?"tp-delivered":""}>{instruction.workerReceivedAt?"✓ ":""}Worker 已接收</span></>}</div>}<button className="tp-button tp-ghost tp-small" onClick={()=>setSnapshot(instruction)}>查看发送时的原文与引用</button>{instruction.status==="queued"&&<p className="tp-small tp-muted">{instruction.archivedAt?"已归档，已退出待执行队列。恢复需求后可重新排队。":"已进入队列，等待当前轮次完成或恢复执行。"}</p>}{instruction.result&&<TaskRunReport taskId={task.id} runId={instruction.runId} result={{...instruction.result,artifacts:instruction.result.artifacts.map(file=>task.attachments.find(current=>current.id===file.id)??file)}} readOnly={task.archived} busy={busy} canResume={!task.archived&&state.phase==="blocked"&&instruction.runId===state.activeRunId} followUpActive={instruction.runId!==state.activeRunId&&["planning","working","reviewing"].includes(state.phase)} approvalCount={detail.approvals.length} onApprove={()=>void action("approve",instruction.runId)} canClarify={!task.archived&&instruction.runId===state.activeRunId&&!["planning","working","reviewing"].includes(state.phase)} onClarify={()=>void action("clarify_report",instruction.runId)} onResume={()=>void action("retry")} onRevise={()=>{setText(`关于第 ${index+1} 条指示的结果，请调整：\n`);composer.current?.scrollIntoView({behavior:"smooth"});}}/>}</div>}</section>)}{!visibleInstructions.length&&<p className="tp-empty">{instructionView==="archived"?"暂无归档需求。":"当前没有需求记录。可添加下一步指示，或恢复归档需求。"}</p>}</div>;
  const tabs=<div className="tp-tabs"><button className="tp-tab" aria-selected={tab==="work"} onClick={()=>setTab("work")}>需求与执行 {currentInstructions.length}</button><button className="tp-tab" aria-selected={tab==="activity"} onClick={()=>setTab("activity")}>全部活动</button><button className="tp-tab" aria-selected={tab==="conversation"} onClick={()=>setTab("conversation")}><MessageSquare/> Codex 对话</button></div>;
  const activity=<div className="tp-feed">{state.events.map(event=><article className="tp-feed-row" key={event.id}><span className="tp-mono tp-muted">{new Date(event.at).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}</span><div><p>{event.text}</p></div></article>)}{activeRun?.jobs.map(job=><TaskExecutionLog key={job.id} taskId={task.id} runId={activeRun.id} job={job}/>)}</div>;
  return <><button className="tp-button tp-ghost tp-back" onClick={onBack}><ArrowLeft/>返回任务板</button>{error&&<div className="tm-error" role="alert">{error}</div>}{state.error&&<div className="tp-alert">{state.error}</div>}{layout==="document"?<div className="tp-doc-layout"><section className="tp-doc-paper">{header}{authorizationDetails}{original}{!task.archived&&compose}</section>{resize}<aside className="tp-doc-execution"><h3>执行轨迹</h3>{agent}{tabs}{tab==="work"?timeline:tab==="activity"?activity:<TaskModeConversation detail={detail} onAddInstruction={focusComposer}/>}</aside></div>:<>{header}{tabs}<div className="tp-detail-grid"><div>{authorizationDetails}{tab==="conversation"?<TaskModeConversation detail={detail} onAddInstruction={focusComposer}/>:<>{layout==="desk"?<details className="tm-original-fold"><summary>原始需求与附件</summary>{original}</details>:original}{tab==="work"?timeline:activity}</>}{!task.archived&&compose}</div>{agent}</div></>}{tab==="work"&&<><div className="tm-workspace-scroll-space" aria-hidden="true"/><nav className="tm-workspace-scroll-nav" aria-label="需求与执行快速跳转"><button type="button" onClick={()=>jumpWorkspace("top")} aria-label="回到顶部" title="回到顶部"><ArrowUpToLine/><span>顶部</span></button><button type="button" onClick={()=>jumpWorkspace("bottom")} aria-label="跳到底部" title="跳到底部"><ArrowDownToLine/><span>底部</span></button></nav></>}{deleteInstruction&&<ModeDialog title="删除需求" onClose={()=>{if(!busy)setDeleteInstruction(null);}} closeOnBackdrop={false} closeOnEscape={!busy}>{error&&<div className="tm-error" role="alert">{error}</div>}<p>确定删除这条需求记录？</p><p className="tp-small tp-muted">{deleteInstruction.agentReceivedAt||deleteInstruction.runId?"这条需求已发送。删除会从需求列表移除，原文与执行结果保留用于追溯，不会撤销已经发送的内容。如需改变执行目标，请追加指示。":"这条需求尚未发送，删除后将取消排队并从列表移除。"}</p><div className="tp-row"><button className="tp-button" disabled={busy} onClick={()=>setDeleteInstruction(null)}>取消</button><button className="tp-button tm-delete-button" disabled={busy} onClick={()=>void manageInstruction(deleteInstruction,"delete")}><Trash2/>确认删除需求</button></div></ModeDialog>}{snapshot&&<ModeDialog title="发送时的需求快照" onClose={()=>setSnapshot(null)}><p className="tp-small tp-muted">版本 {snapshot.snapshot.revision} · {snapshot.createdAt}</p><h3>{snapshot.snapshot.title}</h3><MarkdownContent value={snapshotMarkdown(task.id,snapshot)}/><div className="tp-row tm-attachments">{snapshot.snapshot.attachments.map(file=><a className="tp-attachment" key={file.id} href={`/api/task-mode/tasks/${task.id}/instructions/${snapshot.id}/attachments/${file.id}`} target="_blank" rel="noreferrer">{file.name}</a>)}</div>{snapshot.snapshot.project&&<details className="tm-project-snapshot"><summary>项目说明 · {snapshot.snapshot.project.name}</summary><MarkdownContent value={snapshot.snapshot.project.descriptionMd}/><code>{snapshot.snapshot.project.rootDirectory}</code></details>}<h3>验收标准</h3><MarkdownContent value={snapshotMarkdown(task.id,snapshot,snapshot.snapshot.acceptanceCriteriaMd)}/>{snapshot.snapshot.references.map(ref=><details key={ref.id}><summary>{ref.title} · 版本 {ref.revision}</summary><MarkdownContent value={snapshotMarkdown(task.id,snapshot,ref.markdown)}/></details>)}</ModeDialog>}</>;
}
function stepExpansionKey(taskId:string){return `terminal-apron.task-mode.step-expansion.v1:${taskId}`;}
function readStepOverrides(taskId:string):Record<string,boolean>{
  try{const value:unknown=JSON.parse(window.localStorage.getItem(stepExpansionKey(taskId))??"{}");if(!value||typeof value!=="object"||Array.isArray(value))return {};return Object.fromEntries(Object.entries(value).filter((entry):entry is [string,boolean]=>typeof entry[1]==="boolean"));}catch{return {};}
}
function jobStatus(job:TaskExecutionJob){return {pending:"等待执行",active:"执行中",completed:"已汇报",failed:"失败",interrupted:"已中断"}[job.status];}
export function DocumentsPanel({documents,onSaved,initialId}:{documents:TaskModeDocument[];onSaved:()=>Promise<void>;initialId?:string}) {
  const [selected,setSelected]=useState<TaskModeDocument|undefined>(()=>documents.find(doc=>doc.id===initialId)),[title,setTitle]=useState(()=>documents.find(doc=>doc.id===initialId)?.title??""),[markdown,setMarkdown]=useState(()=>documents.find(doc=>doc.id===initialId)?.markdown??""),[busy,setBusy]=useState(false),[error,setError]=useState("");
  function choose(doc?:TaskModeDocument){setSelected(doc);setTitle(doc?.title??"");setMarkdown(doc?.markdown??"");setError("");}
  async function save(event:FormEvent){event.preventDefault();setBusy(true);setError("");try{const saved=await taskModeApi.saveDocument({id:selected?.id,title,markdown,revision:selected?.revision});setSelected(saved);await onSaved();}catch(error){setError(message(error));}finally{setBusy(false);}}
  return <section><div className="tp-row tp-between"><h1>关联文档</h1><button className="tp-button" onClick={()=>choose()}><Plus/>新建文档</button></div><p className="tp-page-sub">文档可以在任务描述和追加指示中引用，发送时会保留对应版本。</p><div className="tm-documents"><nav>{documents.map(doc=><button key={doc.id} className="tp-button" aria-pressed={selected?.id===doc.id} onClick={()=>choose(doc)}><FileText/>{doc.title}</button>)}</nav><form className="tp-stack" onSubmit={event=>void save(event)}><label className="tm-field">文档名称<input className="tp-input" value={title} onChange={event=>setTitle(event.target.value)} required/></label><RichTaskEditor value={markdown} onChange={setMarkdown} label="文档正文" documents={documents.filter(doc=>doc.id!==selected?.id)}/>{error&&<p className="tm-error" role="alert">{error}</p>}<button className="tp-button tp-primary" disabled={busy||!title.trim()}><Save/>保存文档</button></form></div></section>;
}

export function ProjectsPanel({projects,onChanged,onChoose}:{projects:TaskProjectSummary[];onChanged:()=>Promise<void>;onChoose:(name:string)=>void}) {
  const [editing,setEditing]=useState<{name?:string;creating:boolean}|null>(null);
  return <section className="tm-projects"><div className="tp-row tp-between"><div><h1>项目</h1><p className="tp-page-sub">保存项目说明和代码路径。创建任务时选择项目，即可自动带入路径。</p></div><button className="tp-button tp-primary" onClick={()=>setEditing({creating:true})}><Plus/>新建项目</button></div>
    {projects.length?<div className="tm-project-grid">{projects.map(project=><article className="tm-project-card" key={project.name}><div className="tp-row tp-between"><h2>{project.name}</h2><span className="tp-small tp-muted">{project.taskCount} 项任务</span></div><p className="tp-mono tm-project-path" title={project.rootDirectory}><Folder/>{project.rootDirectory}</p>{project.descriptionMd?<div className="tp-rich tm-project-description"><TaskMarkdown source={project.descriptionMd}/></div>:<p className="tp-small tp-muted">尚未添加项目说明</p>}<div className="tp-row tm-project-actions"><button className="tp-button" onClick={()=>onChoose(project.name)}>查看任务</button><button className="tp-button" onClick={()=>setEditing({name:project.name,creating:false})}>编辑项目</button></div></article>)}</div>:<div className="tp-empty">还没有项目。先创建项目并保存目录，再在任务中选择。</div>}
    {editing&&<ProjectEditor projects={projects} initialProjectName={editing.name} startCreating={editing.creating} onClose={()=>setEditing(null)} onSaved={()=>{setEditing(null);void onChanged();}}/>}
  </section>;
}

function latestAcceptedTaskUpdate(state:TaskModeDetail["state"]):string|undefined {
  for(const run of [...state.runs].reverse()){
    const result=run.result??state.instructions.find(entry=>entry.runId===run.id&&entry.result)?.result;
    for(const job of [...run.jobs].reverse()){
      if(job.status!=="completed"||!job.processed||!job.output||job.role==="worker")continue;
      if(typeof job.output.userUpdate==="string"&&job.output.userUpdate.trim())return job.output.userUpdate;
      if((job.role==="review"||job.role==="execute")&&result&&job.output.summary===result.summary)return result.summary;
      if(job.role==="steer"&&typeof job.output.understanding==="string"&&job.output.understanding.trim())return job.output.understanding;
    }
  }
}
